import { useEffect, useState } from 'react';
import client from '../api/client';

export default function ReportsPage() {
  const [byCorporate, setByCorporate] = useState([]);
  const [overdue, setOverdue] = useState([]);

  useEffect(() => {
    client.get('/reports/progress-by-corporate').then((r) => setByCorporate(r.data));
    client.get('/reports/overdue-tasks').then((r) => setOverdue(r.data));
  }, []);

  return (
    <div style={{ padding: 24 }}>
      <h2>Progress by Corporate Brand</h2>
      <table style={{ borderCollapse: 'collapse', fontSize: 13, marginBottom: 32 }}>
        <thead>
          <tr style={{ background: '#fafafa' }}>
            <th style={th}>Corporate</th><th style={th}>Projects</th><th style={th}>Total tasks</th>
            <th style={th}>Completed</th><th style={th}>% Complete</th>
          </tr>
        </thead>
        <tbody>
          {byCorporate.map((row) => (
            <tr key={row.corporate}>
              <td style={td}>{row.corporate}</td>
              <td style={td}>{row.project_count}</td>
              <td style={td}>{row.total_tasks}</td>
              <td style={td}>{row.completed_tasks}</td>
              <td style={td}>{row.pct_complete}%</td>
            </tr>
          ))}
        </tbody>
      </table>

      <h2>Overdue Tasks ({overdue.length})</h2>
      <table style={{ borderCollapse: 'collapse', fontSize: 13 }}>
        <thead>
          <tr style={{ background: '#fafafa' }}>
            <th style={th}>Task</th><th style={th}>Project</th><th style={th}>Assignee</th><th style={th}>Due</th>
          </tr>
        </thead>
        <tbody>
          {overdue.slice(0, 100).map((row) => (
            <tr key={row.gid}>
              <td style={td}>{row.name}</td>
              <td style={td}>{row.project}</td>
              <td style={td}>{row.assignee}</td>
              <td style={td}>{row.due_on}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

const th = { textAlign: 'left', padding: '6px 10px', borderBottom: '1px solid #eee' };
const td = { padding: '6px 10px', borderBottom: '1px solid #eee' };
